<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('sales');$pageTitle='Sales Reports';$activeMenu='sales-reports';$year=(int)($_GET['year']??date('Y'));$s=db()->prepare("SELECT DATE_FORMAT(sr.sales_month,'%Y-%m') month,CONCAT(u.first_name,' ',u.last_name) person,d.name department,SUM(sr.sales_target) target,SUM(sr.actual_sales) actual,ROUND(SUM(sr.actual_sales)/NULLIF(SUM(sr.sales_target),0)*100,2) achievement FROM sales_records sr JOIN users u ON u.id=sr.salesperson_id JOIN departments d ON d.id=sr.department_id WHERE YEAR(sr.sales_month)=? GROUP BY sr.sales_month,u.id,u.first_name,u.last_name,d.name ORDER BY sr.sales_month DESC,actual DESC");$s->execute([$year]);$rows=$s->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Sales Performance Report</h1><p>Monthly target-to-actual achievement by salesperson.</p></div><button class="btn btn-light border no-print" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Print / PDF</button></div><div class="card-panel"><div class="card-body"><form class="mb-3 no-print"><div class="d-flex gap-2" style="max-width:260px"><input class="form-control" type="number" name="year" value="<?=$year?>"><button class="btn btn-primary">Apply</button></div></form><div class="table-responsive"><table class="table data-table"><thead><tr><th>Month</th><th>Sales Person</th><th>Department</th><th class="text-end">Target</th><th class="text-end">Actual</th><th>Achievement</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['month'])?></td><td><?=e($r['person'])?></td><td><?=e($r['department'])?></td><td class="text-end"><?=money($r['target'])?></td><td class="text-end"><?=money($r['actual'])?></td><td><strong><?=number_format((float)$r['achievement'],1)?>%</strong></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
